          const match = value.match(/^(\\d{4})-(\\d{2})-(\\d{2})$/);
          if (!match) return false;
          const year = Number(match[1]), month = Number(match[2]), day = Number(match[3]);
          if (year < 1 || month < 1 || month > 12 || day < 1) return false;
          const leap = year % 4 === 0 && (year % 100 !== 0 || year % 400 === 0);
          return day <= [31, leap ? 29 : 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31][month - 1];
        };
        app.querySelector('#due-range-form').addEventListener('submit', event => {
          event.preventDefault();
          const from = app.querySelector('#due-from').value.trim();
          const through = app.querySelector('#due-through').value.trim();
          const message = app.querySelector('#message');
          if ((from && !validDate(from)) || (through && !validDate(through))) { message.textContent = 'Due range must use valid YYYY-MM-DD dates'; return; }
          if (from && through && from > through) { message.textContent = 'Due from must not be after Due through'; return; }
          appliedDueFrom = from; appliedDueThrough = through; message.textContent = ''; paintTasks();
        });
        app.querySelector('#default-priority').addEventListener('change', async event => {
          const response = await fetch(`/api/projects/${match[1]}`, { method: 'PATCH', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ defaultPriority: event.target.value }) });
          if (!response.ok) event.target.value = project.defaultPriority;
          else project.defaultPriority = (await response.json()).defaultPriority;
        });
        const paintTasks = () => {
          const visible = tasks.filter(task =>
            (filter.value === 'All' || (filter.value === 'Completed') === Boolean(task.completed)) &&
            (priorityFilter.value === 'All' || task.priority === priorityFilter.value) &&
            ((!appliedDueFrom && !appliedDueThrough) || (Boolean(task.dueDate) && (!appliedDueFrom || task.dueDate >= appliedDueFrom) && (!appliedDueThrough || task.dueDate <= appliedDueThrough)))
          );
          app.querySelector('#task-list').innerHTML = visible.map(task => `<div class="row task-row" data-testid="task-row"><input type="checkbox" id="task-${task.id}" aria-label="Complete ${escapeHtml(task.title)}" ${task.completed ? 'checked' : ''} ${project.archived ? 'disabled' : ''}><label for="task-${task.id}">${escapeHtml(task.title)}</label><input type="text" aria-label="New task title" data-rename-input="${task.id}" value="${escapeHtml(task.title)}" ${project.archived ? 'disabled' : ''}><button type="button" data-rename="${task.id}" ${project.archived ? 'disabled' : ''}>Rename task</button><select aria-label="Task priority" data-priority="${task.id}" ${project.archived ? 'disabled' : ''}><option ${task.priority === 'Low' ? 'selected' : ''}>Low</option><option ${task.priority === 'Normal' ? 'selected' : ''}>Normal</option><option ${task.priority === 'High' ? 'selected' : ''}>High</option></select><input type="text" aria-label="Task due date" data-due-date="${task.id}" value="${escapeHtml(task.dueDate || '')}" ${project.archived ? 'disabled' : ''}><button type="button" data-save-due="${task.id}" ${project.archived ? 'disabled' : ''}>Save due date</button></div>`).join('');
          app.querySelectorAll('#task-list [data-rename]').forEach(button => button.addEventListener('click', async () => {
            const task = tasks.find(item => String(item.id) === button.dataset.rename);
            const input = app.querySelector(`[data-rename-input="${task.id}"]`);
            const title = input.value.trim();
            if (!title) { app.querySelector('#message').textContent = 'Task title is required'; input.focus(); return; }
            const response = await fetch(`/api/projects/${match[1]}/tasks/${task.id}`, { method: 'PATCH', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ title }) });
            if (response.ok) { Object.assign(task, await response.json()); app.querySelector('#message').textContent = ''; paintTasks(); }
          }));
          app.querySelectorAll('#task-list [data-save-due]').forEach(button => button.addEventListener('click', async () => {
            const task = tasks.find(item => String(item.id) === button.dataset.saveDue);
            const input = app.querySelector(`[data-due-date="${task.id}"]`);
            const response = await fetch(`/api/projects/${match[1]}/tasks/${task.id}`, { method: 'PATCH', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ dueDate: input.value }) });
            if (response.ok) { Object.assign(task, await response.json()); app.querySelector('#message').textContent = ''; paintTasks(); }
            else { const result = await response.json(); app.querySelector('#message').textContent = result.error || 'Unable to save due date'; }
          }));
